"""Reconcile immutable local experimental records into the English report."""
import json,hashlib,shutil
from pathlib import Path
from agentic_ai_lab_testing.assessment_studies.interactive_study import obligation_acceptance,balanced_oracle,tagged_oracle
root=Path.cwd();cache=root/'.cache/ascent/interactive';out=root/'.cache/ascent/research-reports/interactive-evidence-study';out.mkdir(parents=True,exist_ok=True)
folders=sorted(p for p in cache.iterdir() if p.is_dir() and (p/'plan.json').exists() and (p/'records.json').exists())
results=[];audit={};allrecords={};protocols={};incorrect=[]
def thinking(c):return (c.get('usage') or {}).get('output_tokens_details',{}).get('reasoning_tokens')
for p in folders:
 plan=json.loads((p/'plan.json').read_text());record=json.loads((p/'records.json').read_text());calls=record['calls'];vs=record['verdicts'];checks=record['checks'];accepted,first=obligation_acceptance(vs)
 complete=bool(calls) and all(isinstance(thinking(c),int) for c in calls)
 repaired=set();failed=False
 for c in calls:
  if failed:repaired.add(c['id'])
  v=next((v for v in vs if v['providerCall']==c['id']),None)
  if v:failed=not v['correct']
 total=sum(thinking(c) or 0 for c in calls)
 row={'run':p.name,'case':plan['case']['case'],'arm':plan['arm'],'stagesCorrect':sum(accepted),'wholeTaskCorrect':all(accepted),'usageComplete':complete,'calls':len(calls),'thinkingObserved':total,'firstWholeCorrectThinking':total if all(accepted) and complete else None,'repairCalls':len(repaired),'repairThinking':sum(thinking(c) or 0 for c in calls if c['id'] in repaired),'failedFinalAnswers':sum(not v['correct'] for v in vs),'toolCalls':len(checks),'branches':sum(len(x['feedback'].get('branches',[])) for x in checks),'reusedBranches':sum(bool(b.get('reusedComponents')) for x in checks for b in x['feedback'].get('branches',[])),'providerErrors':sum(bool(c.get('error')) or c.get('status')!='completed' for c in calls),'completedRun':(p/'result.json').exists(),'runState':'complete' if (p/'result.json').exists() else 'host-aborted','sourceHashes':plan['sourceHashes'],'endpointCorrected':(p/'result.json').exists() and json.loads((p/'result.json').read_text()).get('wholeTaskCorrect')!=all(accepted)}
 results.append(row);allrecords[p.name]=record;protocols[p.name]=plan
 for f in p.glob('*-provider.json'):
  meta=json.loads(f.read_text());terminal=meta.get('terminal') or {};key=terminal.get('id') or hashlib.sha256(f.read_bytes()).hexdigest()
  audit.setdefault(key,{'responseId':terminal.get('id'),'status':terminal.get('status'),'usage':terminal.get('usage'),'seconds':meta.get('providerSeconds'),'error':meta.get('error'),'paths':[]})['paths'].append(str(f.relative_to(root)))
 # Independent check of every exposed native local verdict.
 c=plan['case'];positions={x['id']:i for i,x in enumerate(calls)};checked=0;bad=0
 for x in checks:
  sources=c['changed'] if x['stage']==2 else c['sources'];s={r['name']:r['rows'] for r in sources};sets={n:set(map(tuple,r)) for n,r in s.items()}
  if c['family']=='context-balanced-paths':
   pairs=balanced_oracle(sources);sets.update(balanced=pairs,bridged={(a,b,y) for a,b,z in pairs for z2,y in s['bridge'] if z==z2})
  else:
   flow,permit=tagged_oracle(sources);sets.update(flow=flow,permit=permit)
  for b in x['feedback'].get('branches',[]):
   conditions=b.get('conditions',[{'operation':b.get('operation'),'arguments':b.get('arguments',[])}])
   if b['status']=='unknown' or any(q.get('operation') not in sets for q in conditions):continue
   checked+=1;valid=all(tuple(q['arguments']) in sets[q['operation']] for q in conditions)
   if (b['status']=='supported')!=valid:bad+=1;incorrect.append({'run':p.name,'branch':b})
 row['independentLocalChecks']=checked;row['incorrectLocalChecks']=bad
 row['multiPremiseBranches']=sum(len(b.get('conditions',[]))>1 for x in checks for b in json.loads(x['arguments']).get('branches',[]))
 row['hostRevalidationToolCalls']=sum(bool(x.get('revalidation')) for x in checks)
 # Missing final candidates with fully exposed support before the wrong answer.
 row['supportedOmissions']=[]
 for v in vs:
  if v['correct'] or v['prediction'] is None:continue
  observed={}
  for x in checks:
   if x['stage']!=v['stage'] or positions.get(x['providerCall'],9999)>positions.get(v['providerCall'],0):continue
   for b in x['feedback'].get('branches',[]):
    if b.get('operation'):observed[(b['operation'],tuple(b.get('arguments',[])))]=b['status']
  sources=c['changed'] if v['stage']==2 else c['sources'];needs=next(s for s in sources if s['name']=='needs')['rows']
  for n in needs:
   if n[0] not in set(v['expected'])-set(v['prediction']):continue
   required=[('bridged' if v['stage']==2 else 'balanced',tuple(n[1:4])),('balanced',tuple(n[4:7]))] if c['family']=='context-balanced-paths' else [('flow',tuple(n[i:i+2])) for i in range(1,9,2)]
   if all(observed.get(q)=='supported' for q in required):row['supportedOmissions'].append({'call':v['providerCall'],'job':n[0]})
(out/'results.json').write_text(json.dumps(results,indent=2));(out/'records.json').write_text(json.dumps(allrecords,indent=2));(out/'plans.json').write_text(json.dumps(protocols,indent=2));(out/'provider-audit.json').write_text(json.dumps(list(audit.values()),indent=2))
base=[r for r in results if r['run'].startswith('shared-')];final=[r for r in results if r['run'].startswith('conjunction-') and r['completedRun']];repair=[r for r in results if r['run'].startswith('repair-')]
report=['#+title: Interactive Evidence Reasoning: Local Implementation and Real-Model Study','# SPDX-FileCopyrightText: 2026 tao3k team and Contributors','# SPDX-License-Identifier: Apache-2.0 AND LGPL-2.1-or-later','','* Objective and Library architecture','','The model receives a natural-language domain specification and finite sources. Evidence tools are available from the first provider request. The model chooses candidate paths and local bindings; Scheme checks the registered domain predicates. No model-generated whole-question relational query is required. Evidence Chain manages source-bound support and completed component reuse; Trajectory records observed interactions and provider usage. Local support never certifies task correctness. See [[file:../../features/interactive-evidence-reasoning.org][the Library design]] and [[file:../../features/evidence-responsibilities.org][responsibility contract]].','','* Research foundations and corpus','','[[https://arxiv.org/abs/2210.03629][ReAct]] motivates interleaving exploration and external observations. The provenance readings in the feature design motivate distinct support and temporal-observation owners. These are transfers of design principles, not replications of the papers\' benchmark results. Four independent generated instances span context-specific balanced recursion and mutually recursive flow/permission. Balanced paths require matching labels, recursive concatenation, epsilon and scoped denied edges. Flow requires tuple-specific blocking, tag conversions, explicit permission and mutually recursive grants. Each instance contains 40 opaque job candidates. Each task has three obligations: original goal, same-intent paraphrase on unchanged sources, and a changed-source goal requiring invalidation and rechecking. Complete inputs and gold are in [[file:questions.org][Questions]], but gold never enters the model requests or feedback. Algorithms may have appeared in training; opaque independent instances are not proof of training exclusion.','','* Experimental protocol','','Fresh and retained arms expose identical local-check tools from the first request. No new efficacy calls remain in flight. The host-aborted mutual retained run was recovered from its completed response; the host-aborted balanced fresh run was recovered from four completed checkpoints. Source-only is a separate capability ablation: it can inspect ground source membership, but not derived paths. Provider: deepseek-flash, high reasoning effort, streaming Responses API, max_output_tokens=131072, tool_choice=auto, strict=false. Complete opaque reasoning output items and paired tool outputs are forwarded. Format errors, independent answer failures, provider errors and budget exhaustion are separate outcomes. Up to eight provider calls and three final-answer failures per stage were declared. All completed calls, failures, tool rounds and repairs count through whole-task correctness; output bytes are not a cost proxy. No network CI or remote publication was performed.','','Across all cohorts there are 20 recorded policy trajectories over four independent instances: 18 finished within their declared protocol, two were host-aborted; 16 of the 18 finished trajectories ultimately satisfied the complete task. There are 25 observed incorrect final-answer attempts. These overlapping/adaptive policy branches are not 20 independent benchmark questions. The first exploratory runs had unequal first-response thinking before any feedback. Their outcomes are retained, but do not establish a retention effect. Subsequent shared-prefix pairs uniformly reuse the original fresh-arm first response in both policies; it is charged in full to both policy ledgers and paid only once physically. This is an adaptive confirmation design, not a preregistered population estimate. The new independent multi-premise cohort uses the same sharing rule. Failed-prefix repair retains the first real wrong answer and all its actual preceding usage; no replacement initial answer is sampled.','','The benchmark declares stages 0 and 1 to have the same finite source and goal contract. A later correct stage-1 answer repairs an earlier stage-0 error, while a stage-0 answer cannot pre-answer the later paraphrase. A changed-source stage-2 answer cannot repair earlier-source obligations. This endpoint rule was corrected during audit and tested with three regression cases. Immutable run ledgers retain their historical runtime endpoint; this report recomputes full-task admission from independent verdicts, and flags differences explicitly in results.json. No natural-language-equivalence theorem is claimed.','','* Shared-prefix whole-task comparison','','| Cohort / case | Fresh thinking | Retained thinking | Observed reduction | Quality |','|---------------+----------------+-------------------+--------------------+---------|']
for cohort,rows in [('single-condition',base),('multi-premise',final)]:
 for case in sorted({r['case'] for r in rows}):
  arms={r['arm']:r for r in rows if r['case']==case};f=arms.get('fresh');t=arms.get('retained')
  if not f or not t:report.append(f'| {cohort} / {case} | pending | pending | pending | incomplete pair |');continue
  reduction=f'{100*(1-t["firstWholeCorrectThinking"]/f["firstWholeCorrectThinking"]):.2f}%' if f['firstWholeCorrectThinking'] and t['firstWholeCorrectThinking'] is not None else 'not identifiable'
  report.append(f'| {cohort} / {case} | {f["firstWholeCorrectThinking"] if f["firstWholeCorrectThinking"] is not None else "censored"} | {t["firstWholeCorrectThinking"] if t["firstWholeCorrectThinking"] is not None else "censored"} | {reduction} | {f["stagesCorrect"]}/3 vs {t["stagesCorrect"]}/3 |')
report+=['','* Every trajectory and failed-repair cost','','Repair costs are calls after an observed incorrect final answer, through the next verified correction. The triggering failed call remains in total pre-success thinking. Repair and failed-attempt costs overlap; do not add them as disjoint categories. Runtime source replacement starts a ledger epoch, so whole-task cost here sums actual provider calls across epochs. A censored total is expenditure, not an invented first-correct cost.','','| Run | Accepted obligations | Calls | First-whole-correct thinking | Observed spending | Failed answers | Repair thinking | Branch checks / reused |','|-----+----------------------+-------+------------------------------+-------------------+----------------+-----------------+------------------------|']
for r in results:report.append(f'| {r["run"]} | {r["stagesCorrect"]}/3 | {r["calls"]} | {r["firstWholeCorrectThinking"] if r["completedRun"] and r["firstWholeCorrectThinking"] is not None else "not observed"} | {r["thinkingObserved"]} | {r["failedFinalAnswers"]} | {r["repairThinking"]} | {r["branches"]} / {r["reusedBranches"]} |')
report+=['','* Mechanism audit and negative results','','The single-condition shared balanced retained run omitted two jobs whose two required local predicates were already supported before the failed answer. Its whole-task thinking rose to 130977 versus fresh 43285; repair alone required 15125 thinking tokens after the failure. Every audited exposed local verdict matched the independent oracle. This distinguishes correct engine support from incorrect model composition/consumption. Returning evidence is not proof that the model used it correctly.','','The corrective interface adds model-selected conjunctions: a branch declares up to sixteen local prerequisites. Scheme evaluates their conjunction and returns the candidate branch identifier only when every declared prerequisite holds. It does not choose the prerequisites, infer arbitrary natural-language intent, select the final task answer, or certify that the model omitted no required condition. Fresh and retained both receive this capability. The subsequent independent cohort tests this actual repair; all negative results above remain part of the record.','','The first large mutual retained checkpoint exhausted the 64 native Session cap because the initial controller opened a Session for every branch. The response was complete and provider usage was preserved. Batching fixed the root cause without widening native limits. A second boundary test found the 128-rule cap: batches now reserve rule slots for registered rules and possible materialized-alias rules. Up to 128 candidate checks are split safely. Unknown outcomes remain unknown rather than silently pruning branches.','','* Native load and execution diagnosis','','The observed eight-minute process was doing streamed HTTPS model inference, not dlopen. A one-second process sample showed SSL read/poll, and the event log continued receiving response.reasoning_text.delta. The successful isolated load receipt measured Python import 0.0732 s, validation/load/runtime initialization 0.5212 s, first native describe request 0.000889 s, total including shutdown 0.5960 s. A separate load observation was 1.3123 s. These are single local observations, not a cold-start population estimate. See load-phases.jsonl. They do not qualify another consumer\'s trusted DSL expansion path: a separately observed expander timeout is an independent open gate.','','The 128-candidate fixture completed first check in 1.4281 s and repeated check in 0.6075 s; each used two result references and retained only two native Sessions. All 64 supported and 64 contradicted outcomes were correct. The repeated check reused components for all 128 candidates. Native time savings do not themselves demonstrate model thinking savings.','','* Local qualification and scientific limits','','Actual C ABI and compiled CFFI API suites each pass 14 cases, including first-round function-call pairing, complete reasoning preservation, uncertainty, native multi-premise conjunction, 128-candidate capacity, source invalidation, model-call binding and whole-task scope. Direct Scheme Trajectory suite passes eight cases. Lean EvidenceInteraction and Trajectory compile. Quint EvidenceInteraction passes 10000 sampled traces of 30 steps with seed 13; unknown, observation, stale and missing-condition mutants all violate the invariant. These bounded models specify trusted-checker abstractions and do not prove the native compiler, provider, grader or arbitrary model intent correct.','','Qualification is bound to the frozen local artifact and selected source hashes, not every later concurrent workspace change. The exact source drift and receipts appear in the feature qualification JSON. Reported reductions are complete-case observations with very small denominators. Adaptive repairs and sequential generation can affect results. Prefix-cache tokens, physical requests and policy usage are listed separately. No stable 40–50% reduction, end-to-end dollar saving, training exclusion, or generalized problem-solving guarantee is established.','','* Physical provider audit','']
usage=[x for x in audit.values() if isinstance(x.get('usage'),dict)];th=sum((x['usage'].get('output_tokens_details') or {}).get('reasoning_tokens',0) for x in usage)
report.append(f'Unique observed provider response records: {len(audit)}; usage-bearing records: {len(usage)}; physically reported thinking: {th}. Replayed response IDs are counted once physically and charged to each alternative policy prefix. Runs without final result files remain host-aborted observations. Provider request/response files remain under .cache/ascent/interactive; records, plans and unique usage audit are retained here. The audit includes aborted and superseded controllers, not merely successful runs.')
report+=['','Full per-call usage, decisions, tool arguments and final outputs are in [[file:records.json][records.json]], [[file:provider-audit.json][provider-audit.json]], and [[file:visible-answers.org][visible answers]].']
